// (a) platform behaviour with mixed-case media types
for (const ct of ['Multipart/Form-Data', 'Application/X-WWW-Form-Urlencoded']) {
  try {
    let req: Request
    if (ct.startsWith('M')) {
      const fd = new FormData(); fd.append('a', '1')
      const src = new Request('http://x/', { method: 'POST', body: fd })
      const h = src.headers.get('content-type')!.replace('multipart/form-data', ct)
      req = new Request('http://x/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'content-type': h } })
    } else {
      req = new Request('http://x/', { method: 'POST', body: 'a=1', headers: { 'content-type': ct } })
    }
    const f = await req.formData()
    log('platform', ct, 'OK', f.get('a'))
  } catch (e) { log('platform', ct, 'THROWS', String(e)) }
}

// (b) c.req.formData() then c.req.parseBody()
const app = new Hono()
app.post('/fd-then-parse', async (c) => {
  await c.req.formData()
  try { return c.json({ ok: await c.req.parseBody() }) } catch (e) { return c.json({ err: String(e) }, 500) }
})
app.post('/text-then-parse', async (c) => {
  await c.req.text()
  try { return c.json({ ok: await c.req.parseBody() }) } catch (e) { return c.json({ err: String(e) }, 500) }
})
app.post('/parse-then-fd', async (c) => {
  await c.req.parseBody()
  const fd = await c.req.formData()
  return c.json({ ok: fd.get('a'), keys: Object.keys(c.req.bodyCache) })
})
