  try { return c.json({ ok: await c.req.parseBody() }) } catch (e) { return c.json({ err: String(e) }, 500) }
})
app.post('/parse-then-validator', async (c, next) => { await c.req.parseBody(); await next() }, validator('form', (v) => v), async (c) => c.json({ ok: c.req.valid('form') }))

for (const path of ['/fd-then-parse', '/text-then-parse', '/parse-then-fd', '/validator-then-parse', '/parse-then-validator']) {
  const fd = new FormData(); fd.append('a', '1')
